        for index in 0..6 {
            let augments =
                if index == 5 { "declare global { interface Augmented { fromLastFile?: boolean } }\n" } else { "" };
            std::fs::write(
                root.join(format!("C{index}.tsx")),
                format!(
                    "import type {{ Base, Size }} from './types';\n{augments}\
                     export interface C{index}Props extends Base, Augmented {{ own{index}: number; pick?: (size: Size) => void }}\n\
                     export function C{index}(props: C{index}Props) {{ return null; }}\n"
                ),
            )
            .unwrap();
        }
        (dir, root)
    }

    /// Asks `lanes` programs on a checker with as many lanes about the project's components: their snapshots, the
    /// answer, and whether each snapshot was still held after the first program was released.
    fn answered_on_lanes(root: &Utf8Path, lanes: usize) -> (Vec<u64>, SemanticOutcome, Vec<bool>) {
        let output = extract(&PipelineOptions { src_dirs: vec![root.to_owned()], ..PipelineOptions::default() });
        let request = SemanticRequest::new(root.to_owned(), targets_of(&output));
        let files = root_files(&request);
        let checker = Backend::start(root, lanes).unwrap();
        let runtime = multi_thread();
        let deadline = Duration::from_secs(120);
        let (snapshots, outcome, held) = runtime.block_on(async {
            let programs = Rpc::open_programs(checker.client(), deadline, None, &files, false, lanes).await.unwrap();
            let programs: Vec<Arc<Rpc>> = programs.into_iter().map(Arc::new).collect();
            let snapshots: Vec<u64> = programs.iter().map(|program| program.snapshot).collect();
            let outcome = answer_on(&programs, &request, &files).await.unwrap();
            programs[0].release().await;
            let (client, mut held) = (checker.client(), Vec::new());
            for snapshot in &snapshots {
                // Releasing a snapshot the checker no longer holds fails, as releasing an unknown one does.
                let params = json!({ "snapshot": snapshot }).to_string().into_bytes();
                held.push(client.request_raw("release", params, deadline).await.is_ok());
            }
            (snapshots, outcome, held)
        });
        runtime.block_on(checker.shutdown());
        (snapshots, outcome, held)
    }

    /// Each lane asks a snapshot of its own, derived from the first, and three lanes give the answer one gives: every
    /// program holds every root file, so what the last file declares reaches the components the other lanes answer.
    /// Releasing the first program releases every lane's snapshot. On the base the lanes shared one snapshot.
    #[test]
    fn each_lane_has_a_snapshot_of_its_own_and_they_answer_as_one_program_does() {
        let (_dir, root) = lanes_project();

        let (one_snapshots, one, one_held) = answered_on_lanes(&root, 1);
        let (snapshots, three, held) = answered_on_lanes(&root, 3);

        assert!(one.diagnostics.is_empty() && one.fallbacks.is_empty(), "{one:?}");
        assert_eq!(one.components.len(), 6);
        for component in &one.components {
            let names: Vec<&str> = component.props.iter().map(|prop| prop.name.as_str()).collect();
            assert!(names.contains(&"fromLastFile") && names.contains(&"fromTypes"), "{names:?}");
        }
        assert_eq!(one, three);
        assert_eq!(one_snapshots.len(), 1);
        assert_eq!(snapshots.len(), 3);
        let distinct: std::collections::BTreeSet<u64> = snapshots.iter().copied().collect();
        assert_eq!(distinct.len(), 3, "each lane has a snapshot of its own: {snapshots:?}");
        assert_eq!(
            (one_held, held),
            (vec![false], vec![false; 3]),
            "the first program's release releases every lane's"
        );
    }

    /// The generic components of a run on two lanes are answered in a snapshot derived from the first lane's, whose one
    /// program is reconfigured to take the probe file, not in a second program built from the disk beside both lanes';
    /// and the second lane's snapshot is released before that snapshot is made. The instantiation still forms. On the
    /// base the run made two `createSnapshot`s, the second rooted afresh at every root file, while both lanes lived.
    #[test]
    fn instantiations_are_answered_in_a_snapshot_derived_from_the_first_lane_after_the_others_are_released() {
        let root = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/generic");
        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
        let request = SemanticRequest::new(root.clone(), targets_of(&output));
        let files = root_files(&request);
        let tsconfig = root.join("tsconfig.json");
        let checker = Backend::start(&root, 2).unwrap();
        let runtime = multi_thread();
        let deadline = Duration::from_secs(120);
        let (outcome, lanes, recording, releases) = runtime.block_on(async {
            let programs =
                Rpc::open_programs(checker.client(), deadline, Some(tsconfig.as_str()), &files, true, 2).await.unwrap();
            let programs: Vec<Arc<Rpc>> = programs.into_iter().map(Arc::new).collect();
            let lanes: Vec<(u64, String)> =
                programs.iter().map(|program| (program.snapshot, program.project.clone())).collect();
            let outcome = answer_on(&programs, &request, &files).await.unwrap();
            let recording = programs[0].recording().unwrap();
            programs[0].release().await;
            let releases = programs[0].calls().get("release").copied();
            (outcome, lanes, recording, releases)
        });
        runtime.block_on(checker.shutdown());

        // A generic component comes back only from its instantiation: one that did not form is a fallback.
        let answered: Vec<&str> = outcome.components.iter().map(|component| component.key.as_str()).collect();
        assert!(answered.contains(&"Poly") && answered.contains(&"Anchor"), "{outcome:?}");
        assert!(outcome.fallbacks.iter().all(|fallback| fallback.key == "Configured"), "{:?}", outcome.fallbacks);
        let calls: Vec<(&str, &Value)> = recording
            .as_array()
            .unwrap()
            .iter()
            .map(|call| (call["method"].as_str().unwrap(), &call["params"]))
            .collect();
        let created = calls.iter().filter(|(method, _)| *method == "createSnapshot").count();
        assert_eq!(created, 1, "only the first lane's program is built from the disk");
        let layered = calls
            .iter()
            .position(|(method, params)| *method == "updateSnapshot" && params["changes"].get("fileSystem").is_some())
            .expect("the probe file is added by an update");
        let (first, second) = (&lanes[0], &lanes[1]);
        let changes = &calls[layered].1["changes"];
        assert_eq!(calls[layered].1["snapshot"], json!(first.0), "derived from the first lane's snapshot");
        assert_eq!(changes.get("createPrograms"), None, "no second program beside the first's");
        let reconfigured = changes["reconfigurePrograms"].as_array().unwrap();
        assert_eq!(reconfigured.len(), 1);
        assert_eq!(reconfigured[0]["id"], json!(first.1));
        let roots = reconfigured[0]["rootFiles"].as_array().unwrap();
        assert_eq!(roots.len(), files.len() + 1, "every root file and the probe file: {roots:?}");
        let released_second = calls
            .iter()
            .position(|(method, params)| *method == "release" && params["snapshot"] == json!(second.0))
            .expect("the second lane's snapshot is released");
        assert!(released_second < layered, "the second lane is released before the instantiation snapshot is made");
        // The second lane early, the instantiation snapshot, and the first lane; a release is counted even when it fails,
        // as a second release of the second lane's would.
        assert_eq!(releases, Some(3), "each snapshot is released once");
        // A release that succeeded is recorded; the recording was read before the first lane's own release. The second
        // lane's and the instantiation snapshot's, each once.
        let mut released: Vec<u64> = calls
            .iter()
            .filter(|(method, _)| *method == "release")
            .filter_map(|(_, params)| params["snapshot"].as_u64())
            .collect();
        released.sort_unstable();
        let layered_snapshot = recording.as_array().unwrap()[0..]
            .iter()
            .filter(|call| call["method"] == "updateSnapshot" && call["params"]["changes"].get("fileSystem").is_some())
            .find_map(|call| call["result"]["snapshot"].as_u64())
            .unwrap();
        let mut expected = vec![second.0, layered_snapshot];
        expected.sort_unstable();
        assert_eq!(released, expected);
    }

    /// Stands in for a session: makes snapshot 1 of as many programs as asked on `createSnapshot` (so a run that asked
    /// all the lanes' programs of one snapshot would open), and fails or panics on `updateSnapshot`, which
    /// derives each other lane's; records the snapshots it was told to release, and whether it was closed.
    struct Underived {
        panics: bool,
        released: Arc<Mutex<Vec<u64>>>,
        closed: Arc<std::sync::atomic::AtomicBool>,
    }

    impl Served for Underived {
        fn handle(&self, method: &str, params: &[u8]) -> Result<String, Failure> {
            match method {
                "initialize" => Ok("null".to_string()),
                "createSnapshot" => {
                    // As many programs as asked for.
                    let params: Value = serde_json::from_slice(params).unwrap();
                    let count = params["createPrograms"].as_array().map_or(1, Vec::len);
                    let projects: Vec<Value> = (0..count).map(|n| json!({ "id": format!("p{n}") })).collect();
                    Ok(json!({ "snapshot": 1, "projects": projects }).to_string())
                }
                "updateSnapshot" if self.panics => panic!("checker invariant broken"),
                "updateSnapshot" => Err(Failure { message: "a file nests too deep".to_string(), panicked: false }),
                "release" => {
                    let params: Value = serde_json::from_slice(params).unwrap();
                    self.released.lock().unwrap().push(params["snapshot"].as_u64().unwrap());
                    Ok("null".to_string())
                }
                other => panic!("unexpected {other}"),
            }
        }

        fn discard(&self, _method: &str, _answer: &str) {}

        fn close(&self) {
            self.closed.store(true, std::sync::atomic::Ordering::Release);
        }
    }

    /// A lane whose snapshot cannot be made fails the opening, and the snapshot made before it is released, since no
    /// one will hold it; one that panics stops the checker, which closes its session and every snapshot with it.
    #[test]
    fn a_lane_whose_snapshot_cannot_be_made_releases_the_one_made_before_it() {
        for panics in [false, true] {
            let released = Arc::new(Mutex::new(Vec::new()));
            let closed = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let session = Underived { panics, released: released.clone(), closed: closed.clone() };
            let checker = Backend::spawn(2, move || session).unwrap();
            let runtime = multi_thread();

            let opened = runtime.block_on(Rpc::open_programs(
                checker.client(),
                Duration::from_secs(5),
                None,
                &["/p/a.ts".to_string()],
                false,
                2,
            ));

            assert!(opened.is_err(), "panics: {panics}");
            runtime.block_on(checker.shutdown_within(Duration::from_secs(5)));
            if panics {
                assert!(closed.load(std::sync::atomic::Ordering::Acquire), "the session is closed");
            } else {
                assert_eq!(*released.lock().unwrap(), [1], "the first lane's snapshot is released");
            }
        }
    }

    #[test]
    fn a_name_with_three_or_more_leading_underscores_loses_the_one_the_checker_added() {
        assert_eq!(unescape_leading_underscores("___size"), "__size");
        assert_eq!(unescape_leading_underscores("____triple"), "___triple");
        assert_eq!(unescape_leading_underscores("___0"), "__0");
    }

    #[test]
    fn other_names_are_unchanged() {
        for name in ["size", "_single", "__call", "__type", "default", "", "a___b"] {
            assert_eq!(unescape_leading_underscores(name), name);
        }
    }

    /// A symbol's reference goes back as the text it arrived as, inside the parameters a request or a batch writes.
    #[test]
    fn a_reference_is_written_back_as_it_arrived() {
        let symbol: SymbolInfo =
            serde_json::from_str(r#"{"reference":{"kind":1,"id":4,"file":"7"},"name":"a","flags":0}"#).unwrap();
        let scoped = |extra| Scoped { project: "p0", snapshot: 3, extra };

        let one = serde_json::to_string(&scoped(Asking::Symbol { symbol: &symbol.reference })).unwrap();
        let both = [&symbol.reference, &symbol.reference];
        let many = serde_json::to_string(&scoped(Asking::Symbols { symbols: &both })).unwrap();
        let requests = [
            Batched { method: "isReadonlySymbol", params: scoped(Asking::Symbol { symbol: &symbol.reference }) },
            Batched { method: "getTypesOfType", params: scoped(Asking::Object { object_id: 12 }) },
        ];
        let page = serde_json::to_string(&BatchParams { requests: &requests, continuation_token: Some("t") }).unwrap();

        assert_eq!(symbol.reference.text(), r#"{"kind":1,"id":4,"file":"7"}"#);
        assert_eq!(one, r#"{"project":"p0","snapshot":3,"symbol":{"kind":1,"id":4,"file":"7"}}"#);
        assert_eq!(
            many,
            r#"{"project":"p0","snapshot":3,"symbols":[{"kind":1,"id":4,"file":"7"},{"kind":1,"id":4,"file":"7"}]}"#
        );
        assert_eq!(
            page,
            r#"{"requests":[{"method":"isReadonlySymbol","params":{"project":"p0","snapshot":3,"symbol":{"kind":1,"id":4,"file":"7"}}},{"method":"getTypesOfType","params":{"project":"p0","snapshot":3,"objectId":12}}],"continuationToken":"t"}"#
        );
        assert_eq!(serde_json::to_string(&scoped(Asking::Nothing {})).unwrap(), r#"{"project":"p0","snapshot":3}"#);
    }

    #[test]
    fn a_symbol_arrives_with_the_name_the_source_writes() {
        let symbol: SymbolInfo =
            serde_json::from_value(json!({ "reference": {}, "name": "___size", "flags": 0 })).unwrap();

        assert_eq!(symbol.name, "__size");
    }
}

//! Generic components, read through an instantiation the checker forms itself.
//!
//! The props parameter of `function Poly<E extends ElementType = "div">(props: PolyProps<E>)` is `PolyProps<E>` with `E`
//! open, which has two props where `<Poly />` has every attribute of a `div`. The checker's API has no request that
//! instantiates a signature, so the instantiation is written as source: one file, held in the checker's memory and never
//! on disk (`updateSnapshot` with a `fileSystem` layer), declares for each such component
//!
//! ```ts
//! import type { "Poly" as CaliperComponent0 } from "/project/src/Poly.tsx"; export type CaliperProbe0 = Parameters<typeof CaliperComponent0<"div">>[0];
//! ```
//!
//! and the props are those of `CaliperProbe0`, read as any props type is. The file is added to a snapshot derived from the
//! one that answered the other components, its program rooted at the probe file too, made only when a requested
//! component is generic, so a project without one sends no request more. A line the checker reports an error on (a
//! default it prints with a name the file cannot see) sends that component to its structural result with the error as
//! the reason, and a checker that does not load the file sends them all; a result is never read from an instantiation
//! that did not form.
//!
//! A printed default is text, and the probe file is another module than the component's: a name it prints may resolve
//! there to another symbol than it does in the component's module (the module's own `FormData` against the global
//! one), which forms without an error. So the line also declares each type argument as a type of its own and the
//! signature as `CaliperSignature0`, and a component is read only when each argument is, in the checker that holds the
//! probe file, the very type its signature declares as the default ([`arguments_keep_their_meaning`]). That is the one
//! place the pattern "the probe's type arguments resolve, in the probe file, to what they resolve to in the component's
//! module" is enforced; a default that does not pass sends the component to its structural result.

use std::sync::Arc;

use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticOutcome};
use camino::Utf8Path;
use rustc_hash::FxHashMap;

use crate::component;
use crate::convert::Converter;
use crate::rpc::{CallError, FileDiagnostic, Rpc, SignatureInfo, SignatureKind, SymbolRef};
use crate::{Target, fallback_of};

/// The file the instantiations are declared in, in the project's root directory. It exists only in the checker's memory.
const PROBE_FILE: &str = "__caliper_instantiations__.ts";

/// A generic component to read through an instantiation: the name its module exports it under, and the type arguments.
#[derive(Debug, Clone)]
pub(crate) struct Instantiation {
    pub export: String,
    pub arguments: Vec<String>,
}

/// The type arguments of the instantiation a generic component gets when written without any (`<Poly />`): its first
/// type parameter's declared default, as the checker prints it. The checker fills in the parameters after it from their
/// own defaults, which may refer to the first. `None` when the component is not generic or its first type parameter
/// declares no default: then no instantiation is the one a story renders, and the props keep the open parameters.
pub(crate) async fn default_arguments(rpc: &Rpc, signature: &SignatureInfo) -> Result<Option<Vec<String>>, CallError> {
    if signature.type_parameters.is_empty() {
        return Ok(None);
    }
    // The ids a signature lists are not handles the checker knows until it has answered for them itself.
    let parameters = rpc.type_parameters(signature.id).await?;
    let Some(first) = parameters.first() else { return Ok(None) };
    let Some(default) = rpc.default_of_type_parameter(first.id).await? else { return Ok(None) };
    Ok(Some(vec![rpc.type_to_string(default.id).await?]))
}

/// Whether each type argument the probe file declares for component `index` is the type its signature declares as the
/// default of that parameter, in the checker that holds the probe file: the same type, not one of the same name.
async fn arguments_keep_their_meaning(
    layered: &Rpc,
    probes: &FxHashMap<String, SymbolRef>,
    index: usize,
    instantiation: &Instantiation,
) -> Result<bool, CallError> {
    let Some(signature_alias) = probes.get(&format!("CaliperSignature{index}")) else { return Ok(false) };
    let component = layered.declared_type_of_symbol(signature_alias).await?;
    let signatures = layered.signatures(component.id, SignatureKind::Call).await?;
    let [signature] = signatures.as_slice() else { return Ok(false) };
    let parameters = layered.type_parameters(signature.id).await?;
    for (position, parameter) in parameters.iter().enumerate().take(instantiation.arguments.len()) {
        let Some(default) = layered.default_of_type_parameter(parameter.id).await? else { return Ok(false) };
        let Some(argument_alias) = probes.get(&format!("CaliperArgument{index}_{position}")) else {
            return Ok(false);
        };
        if layered.declared_type_of_symbol(argument_alias).await?.id != default.id {
            return Ok(false);
        }
    }
    Ok(true)
}

/// The line of the probe file that instantiates `instantiation`, the component exported by `file`: the instantiation's
/// props, the component's signature and each type argument, which [`arguments_keep_their_meaning`] compares. Each
/// component is one line, so an error the checker reports is the error of the line it starts on.
fn probe_line(index: usize, file: &Utf8Path, instantiation: &Instantiation) -> String {
    let quoted = |text: &str| serde_json::Value::String(text.to_string()).to_string();
    let declared: String = instantiation
        .arguments
        .iter()
        .enumerate()
        .map(|(position, argument)| format!(" export type CaliperArgument{index}_{position} = {argument};"))
        .collect();
    format!(
        "import type {{ {export} as CaliperComponent{index} }} from {file}; export type CaliperProbe{index} = \
         Parameters<typeof CaliperComponent{index}<{arguments}>>[0]; export type CaliperSignature{index} = typeof \
         CaliperComponent{index};{declared}",
        export = quoted(&instantiation.export),
        file = quoted(file.as_str()),
        arguments = instantiation.arguments.join(", "),
    )
}

/// The written form of an instantiation, for a reason: `Poly<"div">`.
fn written(target: &Target, instantiation: &Instantiation) -> String {
    format!("{}<{}>", target.display_name, instantiation.arguments.join(", "))
}

/// Answers each generic component from its instantiation, in a snapshot derived from `rpc`'s whose program is
/// rooted at `root_files` and the probe file ([`Rpc::layered`]). The snapshot is released before this returns.
pub(crate) async fn answer(
    rpc: &Rpc,
    root_files: &[String],
    project_root: &Utf8Path,
    interner: &PropInterner,
    reverse: bool,
    mut pending: Vec<(Target, Instantiation)>,
) -> Result<SemanticOutcome, CallError> {
    let mut outcome = SemanticOutcome::default();
    // The file's text is part of the request, so it must not depend on the order the components were answered in.
    pending.sort_by(|(a, _), (b, _)| {
        (&a.file_path, &a.display_name, &a.key).cmp(&(&b.file_path, &b.display_name, &b.key))
    });
    let probe = project_root.join(PROBE_FILE);
    let text: Vec<String> = pending
        .iter()
        .enumerate()
        .map(|(index, (target, instantiation))| probe_line(index, &target.file_path, instantiation))
        .collect();
    let all_fall_back = |outcome: &mut SemanticOutcome, reason: &str| {
        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
    };

    let layered = match rpc.layered(root_files, &[(probe.to_string(), text.join("\n"))]).await {
        Ok(layered) => Arc::new(layered),
        Err(CallError::Rejected(message)) => {
            all_fall_back(&mut outcome, &format!("the checker could not instantiate a generic component: {message}"));
            return Ok(outcome);
        }
        Err(fatal) => return Err(fatal),
    };
    let answered = answer_layered(&layered, probe.as_str(), interner, reverse, &pending).await;
    layered.release().await;
    match answered {
        Ok(answered) => Ok(answered),
        Err(CallError::Rejected(message)) => {
            all_fall_back(&mut outcome, &format!("the checker rejected a request: {message}"));
            Ok(outcome)
        }
        Err(fatal) => Err(fatal),
    }
}

async fn answer_layered(
    layered: &Arc<Rpc>,
    probe: &str,
    interner: &PropInterner,
    reverse: bool,
    pending: &[(Target, Instantiation)],
) -> Result<SemanticOutcome, CallError> {
    let mut outcome = SemanticOutcome::default();
    let Some(module) = layered.source_file_symbol(probe).await? else {
        let reason = "the checker did not load the file that instantiates generic components";
        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
        return Ok(outcome);
    };
    let probes: FxHashMap<String, SymbolRef> = layered
        .exports_of_module(&module.reference)
        .await?
        .into_iter()
        .map(|symbol| (symbol.name, symbol.reference))
        .collect();
    let mut errors: FxHashMap<usize, String> = FxHashMap::default();
    // The checker's answer for a file also holds errors it found in other files while forming the instantiations; a
    // line number says nothing about those, so only the probe file's own errors are the errors of a probe line.
    let in_probe = |diagnostic: &FileDiagnostic| diagnostic.file_name.replace('\\', "/") == probe.replace('\\', "/");
    for diagnostic in layered.semantic_diagnostics(probe).await?.into_iter().filter(|d| d.is_error() && in_probe(d)) {
        errors.entry(diagnostic.start_position.line).or_insert_with(|| diagnostic.message());
    }

    let converter = Converter::new(layered.clone(), reverse);
    for (index, (target, instantiation)) in pending.iter().enumerate() {
        let read = match (errors.get(&index), probes.get(&format!("CaliperProbe{index}"))) {
            (Some(error), _) => {
                Err(format!("the instantiation {} could not be formed: {error}", written(target, instantiation)))
            }
            (None, None) => Err(format!("the instantiation {} was not declared", written(target, instantiation))),
            (None, Some(symbol)) => {
                let kept = arguments_keep_their_meaning(layered, &probes, index, instantiation).await;
                match kept {
                    Ok(false) => Err(format!(
                        "the instantiation {} could not be formed: a name in its type arguments means something \
                         else where the instantiation is written than in the component's module",
                        written(target, instantiation)
                    )),
                    Ok(true) => match read_probe(layered, &converter, interner, symbol, target).await {
                        Ok(read) => read,
                        Err(CallError::Rejected(message)) => Err(format!("the checker rejected a request: {message}")),
                        Err(fatal) => return Err(fatal),
                    },
                    Err(CallError::Rejected(message)) => Err(format!("the checker rejected a request: {message}")),
                    Err(fatal) => return Err(fatal),
                }
            }
        };
        match read {
            Ok(component::Props { props, composes, whole }) => {
                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes, whole });
            }
            Err(reason) => outcome.fallbacks.push(fallback_of(target, &reason)),
        }
    }
    Ok(outcome)
}

async fn read_probe(
    layered: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    symbol: &SymbolRef,
    target: &Target,
) -> Result<Result<component::Props, String>, CallError> {
    let props_type = layered.declared_type_of_symbol(symbol).await?;
    component::props_of_type(layered, converter, interner, &props_type, target).await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
