/// symbol's reference as the text it arrived as.
#[derive(Debug, Serialize)]
#[serde(untagged)]
pub(crate) enum Asking<'a> {
    Symbol {
        symbol: &'a SymbolRef,
    },
    Symbols {
        symbols: &'a [&'a SymbolRef],
    },
    /// A declaration, by its node handle.
    Location {
        location: &'a str,
    },
    Type {
        #[serde(rename = "type")]
        type_id: u64,
    },
    Signatures {
        #[serde(rename = "type")]
        type_id: u64,
        kind: u8,
    },
    /// A type printed with `TypeFormatFlags`.
    Printed {
        #[serde(rename = "type")]
        type_id: u64,
        flags: u64,
    },
    /// A type or signature, by the handle the checker gave it.
    Object {
        #[serde(rename = "objectId")]
        object_id: u64,
    },
    File {
        file: &'a str,
    },
    Nothing {},
}

/// A request's parameters: the snapshot and project, then the fields of what it asks.
#[derive(Serialize)]
struct Scoped<'a, E> {
    project: &'a str,
    snapshot: u64,
    #[serde(flatten)]
    extra: E,
}

/// One request of a batch.
#[derive(Serialize)]
struct Batched<'a, E> {
    method: &'static str,
    params: Scoped<'a, E>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct BatchParams<'a, 'b, E> {
    requests: &'b [Batched<'a, E>],
    #[serde(skip_serializing_if = "Option::is_none")]
    continuation_token: Option<&'b str>,
}

