pub(crate) fn symbol_owner_file(symbol: P<Symbol>) -> Option<P<SourceFile>> {
    if symbol.flags().intersects(SymbolFlags::Transient) {
        return None;
    }
    let file = tsrs_ast::get_source_file_of_symbol(symbol)?;
