        static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        if !*ENABLED.get_or_init(|| std::env::var_os("CALIPER_PROFILE_FILE").is_some()) {
            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
        }
        let sent: Value = serde_json::from_slice(&params).unwrap_or(Value::Null);
        let component = COMPONENT.try_with(Clone::clone).unwrap_or_default();
        let started = std::time::Instant::now();
        let answer = self.client.request_raw(method, params, self.deadline).await.map_err(classify)?;
        let elapsed = started.elapsed().as_micros();
        let mut properties = Vec::new();
        let summarize = |v: &Value| {
            let mut kept = v.clone();
            let mut fields = BTreeMap::<String, usize>::new();
            if let Some(symbols) = kept.as_array_mut() {
                for symbol in symbols {
                    if let Some(object) = symbol.as_object_mut() {
                        for (name, value) in object.iter() {
                            *fields.entry(name.clone()).or_default() += value.to_string().len() + name.len() + 3;
                        }
                        object.retain(|name, _| matches!(name.as_str(), "reference" | "name" | "flags" | "declarations" | "parent"));
                    }
                }
            }
            json!({ "bytes": v.to_string().len(), "kept_bytes": kept.to_string().len(), "symbols": v.as_array().map_or(0, Vec::len), "fields": fields })
        };
        if method == "getPropertiesOfType" {
