                for (request, response) in requests.iter().zip(responses) {
                    if request["method"] == "getPropertiesOfType" { properties.push(summarize(&response["result"])); }
                }
            }
        }
        static LOG: std::sync::OnceLock<Mutex<Option<std::io::BufWriter<std::fs::File>>>> = std::sync::OnceLock::new();
        let log = LOG.get_or_init(|| Mutex::new(std::env::var_os("CALIPER_PROFILE_FILE").and_then(|p| std::fs::File::create(p).ok()).map(std::io::BufWriter::new)));
        if let Ok(mut log) = log.lock() {
