/// wiring needs this to know which file to parse and merge, before a
/// `ResolutionContext` (which needs the already-merged `GlobalSourceData`) can
/// exist yet.
pub fn resolve_package_dts_path(
    from_dir: &camino::Utf8Path,
    package_name: &str,
    options: &PipelineOptions,
) -> Option<String> {
    let resolvers = ModuleResolvers::new(options);
    // Resolved as if imported by a file in `from_dir`: the declaration resolver walks up from a file's directory.
    let importing_file = from_dir.join("index.ts");
    react::resolve_package_types_file(&resolvers.main, &resolvers.types_first, &importing_file, package_name)
}

/// The two resolvers of a run, configured the way TypeScript resolves this project's modules (`resolve_options`).
pub(crate) struct ModuleResolvers {
    pub(crate) main: Resolver,
    /// Only `types` and the custom conditions: `resolve_dts` takes the first `exports` key that matches any condition,
    /// so a package listing `"import"` before `"types"` resolves to JavaScript; this one reaches its declarations.
    pub(crate) types_first: Resolver,
}

impl ModuleResolvers {
    pub(crate) fn new(options: &PipelineOptions) -> Self {
        let main = resolve_options(options);
        let custom = custom_conditions(options);
        let types_first =
            ResolveOptions { condition_names: std::iter::once("types".into()).chain(custom).collect(), ..main.clone() };
        ModuleResolvers { main: Resolver::new(main), types_first: Resolver::new(types_first) }
    }
}

/// Module resolution as TypeScript does it for this project. The resolver reads the tsconfig itself (comments,
/// `extends`, `baseUrl`, `paths` wildcards): the configured one, or else the nearest one above each importing file.
/// The governing tsconfig's `customConditions` apply, ESM and CommonJS declaration files resolve, and an import written
/// with a JavaScript extension (`./button.js`) finds its TypeScript source.
fn resolve_options(options: &PipelineOptions) -> ResolveOptions {
    let condition_names = ["types", "import", "require", "default"]
        .into_iter()
        .map(String::from)
        .chain(custom_conditions(options))
        .collect();
    let tsconfig = match &options.tsconfig_path {
        Some(path) => TsconfigDiscovery::Manual(TsconfigOptions {
            config_file: path.as_std_path().to_owned(),
            references: TsconfigReferences::Auto,

    };
    let parameters = rpc.parameters(signature.id).await?;
    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };
    if let Some(arguments) = instantiate::default_arguments(rpc, signature).await? {
        if !export.members.is_empty() {
            return fallback("a generic sub-component reached through its parent's property is not instantiated");
        }
        return Ok(Answer::Instantiate(Instantiation { export: export.name, arguments }));
    }

    let props_type = rpc.type_of_symbol(&first.reference).await?;
    Ok(props_of_type(rpc, converter, interner, &props_type, target).await?.map_or_else(Answer::Fallback, Answer::Props))
}

/// The props a component's props type holds, or why the component keeps its structural result.
pub(crate) async fn props_of_type(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    props_type: &TypeInfo,
    target: &Target,
) -> Result<Result<Props, String>, CallError> {
    if props_type.flags & (flag::ANY | flag::UNKNOWN | flag::UNION | flag::TYPE_PARAMETER) != 0 {
        return Ok(Err("props type is any, unknown, generic or a union".to_string()));
    }

    let own: Vec<SymbolInfo> = rpc
        .properties(props_type.id)
        .await?
        .into_iter()
        .filter(|property| {
            !is_react_declared(property)
                || target.react_wanted.as_ref().is_none_or(|wanted| wanted.contains(&property.name))
        })
        .collect();
    // Only a source the props type reaches whole can be left to a layer the answer adds (`Layering::kept` is asked with
    // them), so they are read before what is left to a layer.
    let (composes, whole) = converter.composes(props_type).await?;
    let whole = converter.as_parents(whole).await?;
    let (own, layered) = leave_to_layers(converter, interner, own, &whole, target).await?;
    let references: Vec<_> = own.iter().map(|property| &property.reference).collect();
    let types = if references.is_empty() { Vec::new() } else { converter.types_of_symbols(&references).await? };

    // React's own descriptions and tags are the structural pass's to give, and its props are most of a component's.
    let asked: Vec<Asked<'_>> = own
        .iter()
        .map(|property| {
            let react_declared = is_react_declared(property);
            Asked {
                property,
                description: !react_declared && !target.described.contains(&property.name),
                tags: !react_declared,
            }
        })
        .collect();
    let keys: Vec<PropKey> = asked
        .iter()
        .zip(&types)
        .map(|(asked, prop_type)| PropKey::of(asked.property, prop_type, asked.description, asked.tags))
        .collect();
    let mut props: Vec<Option<Arc<SemanticProp>>> = keys.iter().map(|key| converter.known_prop(key)).collect();

}

#[derive(Default)]
struct State {
    /// Conversions by (type handle, depth), each entry with the enclosing instantiations it depended on. The handles
    /// are valid inside this snapshot only.
    ///
    /// Why an entry may be reused where [`Entry::holds_in`] says. A conversion reads its context in two ways only: the
    /// depth, which is in the key, and [`Cx::encloses`], the question whether a handle is an instantiation being
    /// expanded around the type. Everything else it reads is the checker's answer about the type, which does not change
    /// inside a snapshot. So a conversion is a deterministic walk whose every step is fixed by the type, the depth and
    /// the answers to those questions, in the order they are asked. Run it again where each handle it asked about has
    /// the same answer, and it asks the same questions in the same order and returns the same type. A handle that the
    /// conversion opened itself is settled inside it (it was found not to enclose the type at its own gate, which is
    /// recorded), so only the handles asked of the outer context are kept. A type in no cycle with its context asks
    /// nothing that encloses it and holds everywhere; one in a cycle holds where the same part of the cycle encloses
    /// it. Entries that hold in a context all agree, so which of them is found first, and so the order in which
    /// types were first reached, cannot show in the output.
    memo: Memo,
    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
    /// By (type handle, whether printed expanded: see [`Rpc::type_to_string_expanded`]).
    printed: Mutex<FxHashMap<(u64, bool), String>>,
    /// The parts of a type by its handle (see [`Parts`]). They are the checker's answer about the type, fixed inside the
    /// snapshot, while the memo converts a type again at another depth or under other instantiations: kept, that
    /// conversion asks for none of them again. Kept for the whole snapshot, since components of one library share
    /// most of their types: kept per component, a program of every Chakra component answered 16 at a time held 16
    /// copies of the same style props' members.
    parts: PartsSeen,
    /// Where props are declared ([`crate::declared`]), kept for the snapshot like the rest.
    declared: crate::declared::Memo,
    /// A map's property count by [`MapKey`]: a map without `as` has one property per key of its constraint and a cut reads
    /// only that count, so a [`settled_count`] list stands for every map of its key (docs/type-checker-integration.md,
    /// "Condition maps", says when that is exact). The handles are valid inside this snapshot only.
    maps: Mutex<FxHashMap<MapKey, usize>>,
    /// The props answered so far ([`crate::component::props_of_type`]), by what makes one ([`PropKey`]).
    props: KeptProps,
    /// The type of each symbol asked about so far, by its reference: what `getTypeOfSymbol` answers for a symbol does
    /// not change inside a snapshot. Chakra's props types are each their own instantiation, so each lists its own
    /// property symbols, but six in ten of those were listed by a component before (the same style props reached
    /// through the same instantiation), and their types need not be asked again.
    symbol_types: Mutex<SymbolTypes>,
    /// What the memo's entries hold, shared with the other lanes of the session ([`Converter::lanes`]).
    trees: Arc<Trees>,
    hits: AtomicU64,
    misses: AtomicU64,
}

/// The type of each symbol asked about, by its reference's text, each type held once however many symbols have it.
#[derive(Default)]
struct SymbolTypes {
    by_symbol: FxHashMap<Box<str>, Arc<TypeInfo>>,
    by_id: FxHashMap<u64, Arc<TypeInfo>>,
}

#[derive(Clone)]
pub(crate) struct Converter {
    rpc: Arc<Rpc>,
    state: Arc<State>,
    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
    reverse: bool,
}

impl Converter {
    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
        Self { rpc, state: Arc::new(State::default()), reverse }
    }

    /// A converter for each program of one session, their memos holding each converted type once between them. The
    /// trees go when the last of the converters does.
    pub(crate) fn lanes(programs: &[Arc<Rpc>], reverse: bool) -> Vec<Self> {
        let trees = Arc::new(Trees::default());
        programs
            .iter()
            .map(|rpc| Self {
                rpc: rpc.clone(),
                state: Arc::new(State { trees: trees.clone(), ..State::default() }),
                reverse,
            })
            .collect()
    }

